import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const GENERATED_HEADER =
  "<!-- GENERATED by scripts/generate-local-agent-source-docs.mjs. Do not edit by hand. -->";
const SOURCE_DOCS_DIRECTORY = "docs/sources";
const CAPABILITIES = [
  ["actionPlanning", "Recommendation / Apply evidence"],
  ["activity", "Privacy-reduced activity summaries"],
  ["contextHealth", "Context Health"],
  ["financialFastPath", "Optimized financial scan"],
  ["glance", "Glance data"],
  ["invocationEvidence", "Invocation evidence"],
  ["planContext", "Plan context"],
  ["rateLimits", "Transcript-reported rate limits"],
  ["statuslineSnapshot", "Statusline / Glance snapshot"]
];

const scriptPath = fileURLToPath(import.meta.url);
const repositoryRoot = dirname(dirname(scriptPath));
const sourceDocsDirectory = join(repositoryRoot, SOURCE_DOCS_DIRECTORY);
const registryPath = join(
  repositoryRoot,
  "packages/core/dist/localAgentFormats/registry.js"
);

const arguments_ = process.argv.slice(2);
const checkOnly = arguments_.length === 1 && arguments_[0] === "--check";
if (arguments_.length > 0 && !checkOnly) {
  throw new Error(
    "Usage: node scripts/generate-local-agent-source-docs.mjs [--check]"
  );
}

const registryModule = await import(pathToFileURL(registryPath).href);
const descriptors = [...registryModule.localAgentFormatDescriptors].sort(
  (left, right) => left.order - right.order || left.id.localeCompare(right.id)
);
registryModule.validateLocalAgentFormatDescriptors(descriptors);
validateDocumentationDescriptors(descriptors);

const expectedFiles = new Map([
  ["README.md", renderIndex(descriptors)],
  ...descriptors.map((descriptor) => [
    `${descriptor.id}.md`,
    renderSourcePage(descriptor)
  ])
]);

if (checkOnly) {
  await checkGeneratedDocs(expectedFiles);
} else {
  await writeGeneratedDocs(expectedFiles);
}

function validateDocumentationDescriptors(values) {
  if (values.length === 0) {
    throw new Error("The local-agent format registry is empty.");
  }

  const ids = new Set();
  for (const descriptor of values) {
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(descriptor.id)) {
      throw new Error(`Unsafe local-agent format id: ${descriptor.id}`);
    }
    if (ids.has(descriptor.id)) {
      throw new Error(`Duplicate local-agent format id: ${descriptor.id}`);
    }
    ids.add(descriptor.id);

    const requiredLists = [
      "howRead",
      "fieldsRead",
      "verified",
      "estimated",
      "notVerified",
      "privacy",
      "limitations"
    ];
    for (const key of requiredLists) {
      if (!Array.isArray(descriptor.docs[key]) || descriptor.docs[key].length === 0) {
        throw new Error(
          `Local-agent format ${descriptor.id} is missing docs.${key}.`
        );
      }
    }
  }
}

function renderIndex(values) {
  const rows = values.map((descriptor) => [
    `[${escapeMarkdown(descriptor.label)}](./${descriptor.id}.md)`,
    inlineCode(descriptor.provider),
    inlineCode(descriptor.confidenceDefaults.validationCoverage),
    inlineCode(descriptor.confidenceDefaults.pricedFinancialEvidence),
    inlineCode(descriptor.confidenceDefaults.unpricedFinancialEvidence)
  ]);

  return finish([
    GENERATED_HEADER,
    "",
    "# Local agent source formats",
    "",
    "These pages are generated from the public local-agent parser registry. They explain how aibill reads each supported on-device format and where its evidence stops.",
    "",
    "Validation coverage and financial evidence are separate axes. A reader can be `live_verified` while its transcript-derived financial values remain `estimated` or `missing`. Local API-equivalent value is never provider-billed spend, savings, or ROI.",
    "",
    markdownTable(
      [
        "Source",
        "Provider",
        "Reader validation",
        "Priced evidence",
        "Unpriced evidence"
      ],
      rows
    ),
    "",
    "To propose another local format, follow the [parser submission guide](../../CONTRIBUTING.md#contributing-a-local-agent-parser). Regenerate these pages with `npm run generate:source-docs`; CI uses `npm run check:source-docs` to reject registry/documentation drift."
  ]);
}

function renderSourcePage(descriptor) {
  const discovery = discoveryPattern(descriptor.discovery);
  const capabilities = CAPABILITIES.map(([key, label]) => [
    label,
    descriptor.capabilities[key] ? "yes" : "no"
  ]);

  return finish([
    GENERATED_HEADER,
    "",
    `# ${escapeMarkdown(descriptor.label)} local transcripts`,
    "",
    "[All local agent sources](./README.md)",
    "",
    markdownTable(
      ["Property", "Registry value"],
      [
        ["Format ID", inlineCode(descriptor.id)],
        ["Provider", inlineCode(descriptor.provider)],
        ["Format", inlineCode(descriptor.docs.format)],
        ["Default local root", inlineCode(`~/${descriptor.defaultHomeRelative.join("/")}`)],
        ["Discovered files", inlineCode(discovery)],
        [
          "Presence-only signal",
          inlineCode(descriptor.discovery.detectionBasename ?? "none")
        ],
        ["Financial reader", inlineCode(descriptor.financialRead)],
        [
          "Reader validation",
          inlineCode(descriptor.confidenceDefaults.validationCoverage)
        ],
        [
          "Priced financial evidence",
          inlineCode(descriptor.confidenceDefaults.pricedFinancialEvidence)
        ],
        [
          "Unpriced financial evidence",
          inlineCode(descriptor.confidenceDefaults.unpricedFinancialEvidence)
        ],
        ["Normalized source", inlineCode(descriptor.sourceRecord.name)],
        ["Observed from", inlineCode(descriptor.sourceRecord.observedFrom)],
        ["Usage granularity", inlineCode(descriptor.sourceRecord.usageGranularity)]
      ]
    ),
    "",
    escapeMarkdown(descriptor.validationNote),
    "",
    "Reader validation describes how the parser has been exercised; it never upgrades the evidence quality of a financial number. Source freshness and the latest sanitized reader error remain runtime observations shown by `aibill doctor --sources`, not static claims from this page.",
    "",
    "## How aibill reads it",
    "",
    bulletList(descriptor.docs.howRead),
    "",
    "## Fields read",
    "",
    bulletList(descriptor.docs.fieldsRead),
    "",
    "## Evidence boundary",
    "",
    "### Verified about the reader",
    "",
    bulletList(descriptor.docs.verified),
    "",
    "### Estimated financial evidence",
    "",
    bulletList(descriptor.docs.estimated),
    "",
    "### Not verified",
    "",
    bulletList(descriptor.docs.notVerified),
    "",
    "## Capabilities",
    "",
    markdownTable(["Capability", "Supported"], capabilities),
    "",
    "## Privacy",
    "",
    bulletList(descriptor.docs.privacy),
    "",
    "Fixtures and generated documentation must never contain a real transcript, prompt, response, credential, account identifier, session identifier, user name, or concrete developer-home path.",
    "",
    "## Limitations",
    "",
    bulletList(descriptor.docs.limitations),
    "",
    "## Recorded fixture IDs",
    "",
    bulletList(descriptor.fixtures.map((fixture) => inlineCode(fixture)), false),
    "",
    "The recorded fixtures are minimal synthetic reproductions of supported shapes. They are regression evidence for the reader—not provider billing evidence."
  ]);
}

function discoveryPattern(discovery) {
  if (discovery.basename) return discovery.basename;
  const extensions = discovery.extensions ?? (
    discovery.extension ? [discovery.extension] : []
  );
  const extension = extensions.length > 1
    ? `.{${extensions.map((value) => value.replace(/^\./, "")).join(",")}}`
    : extensions[0] ?? "";
  const ancestor = discovery.ancestorBasename
    ? `${discovery.ancestorBasename}/**/`
    : "";
  if (discovery.basenamePrefix) return `${discovery.basenamePrefix}*${extension}`;
  return `${ancestor}*${extension}`;
}

function bulletList(values, shouldEscape = true) {
  return values
    .map((value) => `- ${shouldEscape ? escapeMarkdown(value) : value}`)
    .join("\n");
}

function markdownTable(headers, rows) {
  return [
    `| ${headers.map(escapeTableCell).join(" | ")} |`,
    `| ${headers.map(() => "---").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map(escapeTableCell).join(" | ")} |`)
  ].join("\n");
}

function escapeTableCell(value) {
  return String(value).replaceAll("|", "\\|").replaceAll("\n", " ");
}

function escapeMarkdown(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("\r", "")
    .replaceAll("\n", " ");
}

function inlineCode(value) {
  const text = String(value);
  const longestRun = Math.max(0, ...[...text.matchAll(/`+/g)].map((match) => match[0].length));
  const fence = "`".repeat(longestRun + 1);
  const padding = text.startsWith("`") || text.endsWith("`") ? " " : "";
  return `${fence}${padding}${text}${padding}${fence}`;
}

function finish(lines) {
  return `${lines.join("\n")}\n`;
}

async function existingMarkdownFiles() {
  try {
    return (await readdir(sourceDocsDirectory))
      .filter((name) => name.endsWith(".md"))
      .sort();
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
}

async function checkGeneratedDocs(expected) {
  const problems = [];
  const existing = await existingMarkdownFiles();
  const expectedNames = [...expected.keys()].sort();

  for (const name of expectedNames) {
    const path = join(sourceDocsDirectory, name);
    let actual;
    try {
      actual = await readFile(path, "utf8");
    } catch (error) {
      if (error?.code === "ENOENT") {
        problems.push(`missing ${relative(repositoryRoot, path)}`);
        continue;
      }
      throw error;
    }
    if (actual !== expected.get(name)) {
      problems.push(`stale ${relative(repositoryRoot, path)}`);
    }
  }

  for (const name of existing) {
    if (!expected.has(name)) {
      problems.push(`unexpected ${join(SOURCE_DOCS_DIRECTORY, name)}`);
    }
  }

  if (problems.length > 0) {
    for (const problem of problems) console.error(`source docs: ${problem}`);
    console.error("Run `npm run generate:source-docs` and commit the result.");
    process.exitCode = 1;
    return;
  }

  console.log(`Source docs are current (${expectedNames.length} files).`);
}

async function writeGeneratedDocs(expected) {
  await mkdir(sourceDocsDirectory, { recursive: true });
  const existing = await existingMarkdownFiles();

  for (const name of existing) {
    if (!expected.has(name)) await rm(join(sourceDocsDirectory, name));
  }
  for (const [name, content] of expected) {
    await writeFile(join(sourceDocsDirectory, name), content, "utf8");
  }

  console.log(`Generated ${expected.size} source documentation files.`);
}
